CAT = "fitrkVehicle"; SEG = "VEH"
# Traficom topic areas for C, CE, D, DE: vehicle construction and operation, lubrication and
# anti-freezing, methods for finding faults, preventive maintenance and routine repairs.
Q = [
("When is the engine oil level of a truck read most accurately?",
 "Level ground, engine off", ["With the engine running", "Right after a hill climb", "With the cab tilted"],
 "Park on level ground and let the oil drain back for a few minutes after stopping, then read the dipstick or the dashboard level."),
("What does the coolant's antifreeze protect the engine from in a Finnish winter?",
 "Freezing and corrosion", ["Low oil pressure in winter", "Diesel fuel waxing", "Worn piston rings"],
 "Antifreeze in the coolant stops it freezing and cracking the engine, and its additives prevent corrosion. Check the freezing point before winter."),
("Summer-grade diesel can turn waxy in hard frost. What is the result?",
 "Blocked fuel filters", ["A higher top speed", "A cleaner exhaust", "A drop in the oil level"],
 "Paraffin wax clogs the filter and the engine loses power or stops. Finnish stations sell winter and arctic grades for the cold season."),
("Why is a truck's engine block heater used on cold mornings?",
 "Easier starts, less wear", ["To charge the battery", "To defrost the trailer", "To raise the tyre pressure"],
 "A block heater warms the engine before starting, which reduces wear and cold-start emissions and gives cab heat sooner."),
("Why does a Euro 6 truck have a second, blue-capped tank next to the fuel tank?",
 "Cutting nitrogen oxides", ["Cooling the engine", "Lubricating the gearbox", "Cleaning the windscreen"],
 "AdBlue (urea solution) is sprayed into the exhaust before the SCR catalyst to turn nitrogen oxides into nitrogen and water."),
("The AdBlue tank runs empty on a trip. What will a modern truck normally do?",
 "Limit engine power", ["Run as normal", "Switch to petrol", "Stop the tachograph"],
 "Emission systems reduce engine power or speed when AdBlue runs out or the system fails, so keep it topped up."),
("What does a diesel particulate filter (DPF) need from time to time?",
 "Regeneration", ["A coolant flush", "New brake fluid", "A tyre rotation"],
 "Soot collected in the DPF is burnt off in a regeneration. Short low-speed trips can stop it finishing; follow the dashboard prompts."),
("On the motorway the engine oil pressure lamp lights up red and stays on. What is the correct action?",
 "Stop and switch off", ["Drive on to the next service", "Top up the coolant", "Rev the engine to raise pressure"],
 "Low oil pressure can wreck the engine in minutes. Stop safely, switch off and check the oil level before going on."),
("The battery charge warning light stays on while driving. What is a likely cause?",
 "A broken alternator belt", ["A slow puncture in a tyre", "Low brake fluid level", "A blocked fuel filter"],
 "A charge warning means the alternator is not charging, often because of a broken or slipping belt. The same belt may also drive the water pump."),
("Thick black smoke comes from the exhaust when accelerating hard. What does it usually point to?",
 "Too little air for the fuel", ["Engine oil being burnt", "Coolant in the cylinders", "A normal cold morning start"],
 "Black smoke means incomplete combustion, often from a blocked air filter or faulty injectors. Blue smoke points to oil, white smoke to coolant or a cold engine."),
("What should you do with the water separator on the fuel filter in daily checks?",
 "Drain off any water", ["Fill it with diesel", "Add antifreeze to it", "Remove it in winter"],
 "Water in diesel causes corrosion and freezes in winter. Drain the separator as the maker instructs."),
("When should a truck's differential lock be used?",
 "Moving off on ice or mud", ["At motorway speeds", "When turning tight corners", "On dry asphalt downhill"],
 "Engage the diff lock when a drive wheel spins on ice or mud, at low speed and going straight, and release it before turning."),
("Why should you let a hot turbocharged engine idle briefly before switching off after hard work?",
 "To cool the turbocharger", ["To charge the tachograph", "To warm the cab", "To fill the air tanks"],
 "A short idle after a long climb lets oil cool the turbo bearings. Keep it short: the Road Traffic Act bans needless idling."),
("Which is part of a driver's daily walk-around check?",
 "Tyres, lights and leaks", ["Engine timing and valves", "A gearbox oil change", "Wheel alignment angles"],
 "Before setting off, check lights, indicators, tyres, wheel nuts, leaks, mirrors, wipers, the load and the coupling. Report faults in writing."),
("Who is responsible for a truck's roadworthiness when you drive it on the road?",
 "Driver and owner both", ["Only the workshop", "Only the owner", "Only the inspection station"],
 "The driver must make sure the vehicle is in roadworthy condition before and during driving, even when the owner looks after its maintenance."),
("The windscreen washer fluid freezes in the jets on a cold day. What should you have used?",
 "Winter washer fluid", ["Plain tap water", "Diluted engine coolant", "Engine oil additive"],
 "Use winter washer fluid with enough antifreeze for the temperature. A dirty windscreen hides hazards in slush and road salt."),
("On a truck with an automated gearbox, how should you hold the vehicle still on a slope?",
 "With the brake", ["By slipping the clutch", "By revving the engine", "In neutral, no brake"],
 "Use the service or hill-start brake to hold the vehicle; riding the clutch overheats it. On an automated box the system controls the clutch."),
("The steering feels heavy and the power steering warning lights up. What is the safest step?",
 "Stop and check the fault", ["Drive faster to ease it", "Pump the brake pedal", "Turn the wheel to full lock"],
 "Loss of power steering makes a heavy vehicle hard to steer. Stop where safe, check the fluid and belt, and call for help if needed."),
("Your truck's coolant temperature gauge rises into the red on a long climb. What should you do?",
 "Stop and let it cool", ["Open the radiator cap at once", "Keep climbing at full power", "Pour cold water on the engine"],
 "Stop safely and let the engine cool. Opening a hot radiator cap can spray scalding coolant."),
("What do greasing points on the chassis and the fifth wheel need?",
 "Regular lubrication", ["Antifreeze each winter", "Brake fluid", "Nothing, they are sealed"],
 "Moving joints, spring pins and the fifth wheel plate wear quickly without grease. Follow the maintenance schedule, more often in winter salt."),
]
